unsigned int gdx_lookup_common_asset_rom_offset(unsigned long long sym_addr) {
    int i;
    for (i = 0; sCommonAssetRomMap[i].sym != NULL; i++) {
        if ((unsigned long long)(size_t)sCommonAssetRomMap[i].sym == sym_addr)
            return sCommonAssetRomMap[i].rom_offset;
    }
    return 0U;
}

const char* gdx_lookup_common_asset_o2r_key(unsigned long long sym_addr) {
    int i;
    for (i = 0; sCommonAssetRomMap[i].sym != NULL; i++) {
        if ((unsigned long long)(size_t)sCommonAssetRomMap[i].sym == sym_addr)
            return sCommonAssetRomMap[i].o2r_key;
    }
    return NULL;
}
