typedef struct { void* sym; unsigned char segment; unsigned int rom_base; unsigned char compressed; unsigned int offset; unsigned int size; unsigned int image_size; const char* o2r_key; } GdxAssetRangeEntry;
static const GdxAssetRangeEntry sAssetRangeMap[] = {
    { aPositionDigitTexs, 0x04u, 0x001B8550U, 0u, 0x00013DE0U, 0x00004600U, 0x00029EA0U, "hud_gfx/aPositionDigitTexs" },
    { aPositionOrdinalSuffixTexs, 0x04u, 0x001B8550U, 0u, 0x00019020U, 0x00000C80U, 0x00029EA0U, "hud_gfx/aPositionOrdinalSuffixTexs" },
    { NULL, 0u, 0U, 0u, 0U, 0U, 0U, NULL }
};

/* Symbol lookups run for every translated pointer of every display-list
 * command each frame. A linear scan of the segment map dominates frame
 * time, so both lookups binary-search a lazily built sorted index. */
typedef struct { unsigned int low32; int idx; } GdxAssetIndexEntry;
static GdxAssetIndexEntry sAssetSegmentIndex[sizeof(sAssetSegmentMap) / sizeof(sAssetSegmentMap[0])];
static int sAssetSegmentIndexCount = 0;
static int sAssetSegmentIndexBuilt = 0;

static void gdx_build_asset_index(void) {
    int n, gap, i, j;
    if (sAssetSegmentIndexBuilt) return;
    for (n = 0; sAssetSegmentMap[n].sym != NULL; n++) {
        sAssetSegmentIndex[n].low32 = (unsigned int)(size_t)sAssetSegmentMap[n].sym;
        sAssetSegmentIndex[n].idx = n;
    }
    for (gap = n / 2; gap > 0; gap /= 2) {
        for (i = gap; i < n; i++) {
            GdxAssetIndexEntry t = sAssetSegmentIndex[i];
            for (j = i; j >= gap && sAssetSegmentIndex[j - gap].low32 > t.low32; j -= gap) {
                sAssetSegmentIndex[j] = sAssetSegmentIndex[j - gap];
            }
            sAssetSegmentIndex[j] = t;
        }
    }
    sAssetSegmentIndexCount = n;
    sAssetSegmentIndexBuilt = 1;
}

/* Greatest index entry with low32 <= key, or -1. */
static int gdx_asset_index_floor(unsigned int key) {
    int lo = 0, hi, best = -1;
    gdx_build_asset_index();
    hi = sAssetSegmentIndexCount - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (sAssetSegmentIndex[mid].low32 <= key) { best = mid; lo = mid + 1; }
        else { hi = mid - 1; }
    }
    return best;
}

int gdx_lookup_asset_segment(unsigned int sym_low32, unsigned char* segment, unsigned int* rom_base,
                             unsigned char* compressed, unsigned int* offset, unsigned int* image_size) {
    int i;
    int f = gdx_asset_index_floor(sym_low32);
    if (f >= 0 && sAssetSegmentIndex[f].low32 == sym_low32) {
        i = sAssetSegmentIndex[f].idx;
        if (segment != NULL) *segment = sAssetSegmentMap[i].segment;
        if (rom_base != NULL) *rom_base = sAssetSegmentMap[i].rom_base;
        if (compressed != NULL) *compressed = sAssetSegmentMap[i].compressed;
        if (offset != NULL) *offset = sAssetSegmentMap[i].offset;
        if (image_size != NULL) *image_size = sAssetSegmentMap[i].image_size;
        return 1;
    }
    for (i = 0; sAssetRangeMap[i].sym != NULL; i++) {
        unsigned int base = (unsigned int)(size_t)sAssetRangeMap[i].sym;
        unsigned int delta = sym_low32 - base;
        if (delta < sAssetRangeMap[i].size) {
            if (segment != NULL) *segment = sAssetRangeMap[i].segment;
            if (rom_base != NULL) *rom_base = sAssetRangeMap[i].rom_base;
            if (compressed != NULL) *compressed = sAssetRangeMap[i].compressed;
            if (offset != NULL) *offset = sAssetRangeMap[i].offset + delta;
            if (image_size != NULL) *image_size = sAssetRangeMap[i].image_size;
            return 1;
        }
    }
    return 0;
}

/* Interior-pointer resolution: game DLs reference vertex data at symbol+offset
 * (e.g. gSPVertex(&D_3000C98[64], ...)). Exact matching misses those, and the
 * pointer would otherwise resolve into the zero-filled placeholder BSS array,
 * producing origin-vertex spike polygons. Match within each symbol's byte size. */
int gdx_lookup_asset_segment_interior(unsigned int sym_low32, unsigned char* segment, unsigned int* rom_base,
                                      unsigned char* compressed, unsigned int* offset, unsigned int* image_size) {
    int i;
    unsigned int base, delta;
    int f = gdx_asset_index_floor(sym_low32);
    if (f < 0) return 0;
    /* Placeholder arrays are distinct linker objects, so address ranges never
       overlap: only the greatest base at or below the pointer can contain it. */
    i = sAssetSegmentIndex[f].idx;
    base = sAssetSegmentIndex[f].low32;
    delta = sym_low32 - base;
    if (delta != 0u && delta < sAssetSegmentMap[i].sym_size) {
        if (segment != NULL) *segment = sAssetSegmentMap[i].segment;
        if (rom_base != NULL) *rom_base = sAssetSegmentMap[i].rom_base;
        if (compressed != NULL) *compressed = sAssetSegmentMap[i].compressed;
        if (offset != NULL) *offset = sAssetSegmentMap[i].offset + delta;
        if (image_size != NULL) *image_size = sAssetSegmentMap[i].image_size;
        return 1;
    }
    return 0;
}

/* [traffic] HAND-EDIT (see C-R5.2 caveat in tools/gen_asset_bindings.py): binary search via the
 * sorted index instead of the linear ~2.5k-row scan. The bridge calls this for EVERY
 * o2r-candidate SETTIMG it rewrites (~65/frame in a race), which made the linear form ~160k
 * comparisons per frame on the ARM11. Exact-match semantics are identical: placeholder symbols
 * are distinct linker objects, so a low32 matches at most one row. */
const char* gdx_lookup_asset_segment_o2r_key(unsigned int sym_low32) {
    int f = gdx_asset_index_floor(sym_low32);
    if (f >= 0 && sAssetSegmentIndex[f].low32 == sym_low32) {
        return sAssetSegmentMap[sAssetSegmentIndex[f].idx].o2r_key;
    }
    return NULL;
}

const char* gdx_find_o2r_key_by_abs_rom_offset(unsigned int abs_rom_offset) {
    int i;
    for (i = 0; sAssetSegmentMap[i].sym != NULL; i++) {
        if (sAssetSegmentMap[i].compressed == 0u &&
            sAssetSegmentMap[i].rom_base + sAssetSegmentMap[i].offset == abs_rom_offset)
            return sAssetSegmentMap[i].o2r_key;
    }
    return NULL;
}

