/* Byte-pointer swaps: fixup offsets carry no alignment guarantee, and a
 * misaligned u16/u32 deref is UB the 32-bit ARM target may not forgive. */
static void gdx_bswap16_at(unsigned char* p) {
    unsigned char b0 = p[0];
    p[0] = p[1];
    p[1] = b0;
}

static void gdx_bswap32_at(unsigned char* p) {
    unsigned char b0 = p[0];
    unsigned char b1 = p[1];
    p[0] = p[3];
    p[1] = p[2];
    p[2] = b1;
    p[3] = b0;
}

void gdx_fixup_asset_segment_image(unsigned char segment, unsigned int rom_base, unsigned char* data, unsigned int size) {
    int i;
    for (i = 0; sAssetFixups[i].kind != 0u; i++) {
        unsigned int j;
        unsigned int off = sAssetFixups[i].offset;
        unsigned int bytes = sAssetFixups[i].size;
        if (sAssetFixups[i].segment != segment || sAssetFixups[i].rom_base != rom_base) continue;
        if (off >= size || bytes > size - off) continue;
        if (sAssetFixups[i].kind == 1u) {
            for (j = 0; j + 4 <= bytes; j += 4) {
                gdx_bswap32_at(data + off + j);
            }
        } else if (sAssetFixups[i].kind == 2u) {
            for (j = 0; j + 2 <= bytes; j += 2) {
                gdx_bswap16_at(data + off + j);
            }
        } else if (sAssetFixups[i].kind == 3u) {
            for (j = 0; j + 16 <= bytes; j += 16) {
                unsigned int k;
                for (k = 0; k < 12; k += 2) {
                    gdx_bswap16_at(data + off + j + k);
                }
            }
        }
    }
}

void gdx_register_asset_segment_command_ranges(unsigned char segment, unsigned int rom_base, unsigned char* data, unsigned int size) {
    int i;
    extern void gdx_register_host_n64_command_range(void* ptr, size_t size);
    for (i = 0; sAssetFixups[i].kind != 0u; i++) {
        unsigned int off = sAssetFixups[i].offset;
        unsigned int bytes = sAssetFixups[i].size;
        if (sAssetFixups[i].kind != 1u) continue;
        if (sAssetFixups[i].segment != segment || sAssetFixups[i].rom_base != rom_base) continue;
        if (off >= size || bytes > size - off) continue;
        gdx_register_host_n64_command_range(data + off, bytes);
    }
}
